#### Tailwind CSS Configuration

Tailwind CSS is configured via `tailwind.config.ts`. Design tokens are mapped as CSS custom properties in `globals.css` and referenced by the Tailwind config (see GUID-APP-UI-001 and STD-APP-UI-001 for the full token taxonomy and usage standards).

```typescript
// tailwind.config.ts (excerpt)
import type { Config } from 'tailwindcss';

const config: Config = {
  content: ['./src/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        background: 'hsl(var(--background))',
        foreground: 'hsl(var(--foreground))',
        primary: {
          DEFAULT: 'hsl(var(--primary))',
          foreground: 'hsl(var(--primary-foreground))',
        },
        // ... additional token mappings per GUID-APP-UI-001
      },
    },
  },
};

export default config;
```
